.view_S1N13_top span{color:#2980b9;} @media screen and (max-width: 39.9375em) { } 더불어민주당 천영미 안산시장 예비후보가 홍희관 전 안산시환경재단 대표이사(전 안산시장 예비후보)와 손을 잡고 안산의 발전을 위한 ‘정책연대’를 공식 선언했다. 천영미 예비후보 캠프 측은 17일, 홍희관 전 대표이사가 천 후보의 비전과 정책에 깊이 공감하며 안산의 승리를 위해 정책 파트너로서 함께하기로 뜻을 모았다고 밝혔다. 이번 연대는 안산의 행정과 환경, 미래 산업 전반을 아우르는 전문가들의 결합이라는 점에서 지역 정가의 이목을 집중시키고 있다. 특히 두 사람은 이번 정책연대의 핵심 과제로 ‘AI 데이터센터 유치 및 디지털 산업 생태계 조성’을 꼽았다. 홍희관 전 대표이사는 안산시환경재단을 이끌었던 경험을 바탕으로, 데이터센터 유치 시 발생할 수 있는 환경적 고려사항과 에너지 효율화 방안에 대한 전문적인 견해를 제시했다. 이에 천영미 후보는 자신이 구상해온 ‘첨단 AI 산업 도시 안산’의 청사진에 홍 전 대표의 실무적 통찰력을 더해, 보다 실현 가능하고 지속 가능한 미래 정책을 완성해 나가기로 합의했다. 홍희관 전 대표이사는 “안산의 변화를 이끌 적임자는 준비된 행정가이자 진정성 있는 리더인 천영미 후보라고 확신한다”며 “특히 AI 데이터센터 등 안산의 산업 구조를 재편할 핵심 정책들이 차질 없이 추진될 수 있도록 모든 역량을 보태겠다”고 지지 의사를 밝혔다. 이에 천영미 예비후보는 “안산의 환경과 행정 분야에서 탁월한 전문성을 쌓아온 홍희관 전 대표이사의 합류는 가뭄에 단비와 같은 큰 힘이 된다”며 “단순한 단일화를 넘어 안산의 미래 먹거리를 함께 고민하는 ‘정책 공동체’로서, 반드시 승리해 시민들께 약속한 AI 중심의 첨단 산업 도시를 선물하겠다”고 강조했다. 이번 정책연대를 통해 천영미 후보는 당내 경선은 물론 본선 경쟁력을 한층 강화하게 되었으며, 향후 홍 전 대표이사와 함께 구체적인 안산 발전 공약을 순차적으로 발표하며 세몰이에 나설 예정이다. $(function() { const copyUrlOptions=document.querySelectorAll(".urlBtns, .sns_clipboard"); // 주소복사 이벤트 (v11-fl-v2 수정) copyUrlOptions.forEach(selector=>{ selector.addEventListener("click", (e)=>{ const target=e.target, targetBtn=target.closest("[data-clipboard-text]"); if (targetBtn===null) return; const url=targetBtn.getAttribute("data-clipboard-text")||""; Util.copyToClipboardToast(selector, '', url); }); }); // 사진 lightBox 이벤트 if (typeof ImageViewer != "undefined") { new ImageViewer(".photo-layout", 0); } }); 권영창 기자 p3ccks@hanmail.net 다른기사 보기 키워드 #안산시장
