.view_S1N13_top span{color:#2980b9;} @media screen and (max-width: 39.9375em) { } 김철민 예비후보(좌) 김철진 예비후보(우) 메가 원팀 구성 [사진=김철민 예비후보] 더불어민주당 안산시장 본경선에서 ‘정책 전문가’로 활약했던 김철진 예비후보가 김철민 예비후보와 손을 잡고 ‘생명과 안전’이 최우선인 안산을 만들기 위한 대장정에 합류했다. 이로써 김철민 예비후보는 당내 주요 세력을 모두 아우르는 ‘메가 원팀’을 구성하며 본선 승리를 향한 압도적인 대세론을 굳히게 됐다. 김철진 예비후보는 21일 오후 5시, 안산시 단원구 ‘김철민 동행캠프’에서 기자회견을 열고 김철민 예비후보에 대한 지지 선언과 함께 ‘생명·존중·안전도시 안산’을 위한 정책연대를 공식 발표했다. 이날 김철진 예비후보는 과거 교육 현장에서 직접 가르쳤던 제자 27명을 세월호 참사로 떠나보내야 했던 개인적인 아픔을 담담히 술회하며, “안산의 리더에게 가장 필요한 덕목은 시민의 생명을 지키는 무한 책임감”이라고 강조했다. 이어 “김철민 후보의 강력한 리더십과 뚝심이야말로 ‘생명존중 안전도시’ 안산을 실현할 유일한 적임자라고 판단했다”고 지지 배경을 밝혔다. 양측은 이번 정책연대를 통해 생명존중 안전도시 안산 선포, 안전문화제 추진, 안산 대개조 프로젝트 내 안전 정책 강화 등 김철진 예비후보가 제시한 핵심 가치들을 시정에 적극 반영하기로 합의했다. 이번 지지 선언은 지난 16일 박천광 예비후보의 정책연대와 17일 고영인·부좌현 전 국회의원의 합류에 이은 것으로, 지역 정가에서는 김철민 예비후보를 중심으로 한 ‘민주당 필승 대세론’이 완성됐다는 분석이 지배적이다. 특히 본선에서 국민의힘 소속 이민근 현 시장을 꺾고 안산의 자부심을 되찾아올 수 있는 가장 강력한 본선 경쟁력을 갖춘 후보라는 점에 지지세가 결집하고 있다. 김철민 예비후보는 “안산의 아픔을 가슴에 품고 정책을 갈고닦아온 김철진 후보의 결단에 깊은 경의를 표한다”며, “김 후보의 ‘생명·안전’ 가치를 김철민의 ‘안산 대개조’ 최우선 과제로 삼아 시민이 안심하고 살 수 있는 안산을 반드시 만들겠다”고 화답했다. 한편, 김철민 동행캠프는 이번 원팀 구성을 더욱 공고히 하기 위해 김철진 캠프에서 상임선거대책위원장을 맡았던 정용상 위원장을 ‘동행캠프 총괄선대본부장’으로 전격 임명했다. 정용상 총괄본부장은 “김철민 후보가 경선에서 압승할 수 있도록 최선을 다하겠다”는 포부를 밝혔다. 캠프 관계자는 “안산 지역 정서와 선거 행정에 정통한 정용상 총괄본부장 체제가 구축됨에 따라, 흩어졌던 민주당의 지지 세력을 하나로 묶는 ‘용광로 선대위’가 본격 가동될 것”이라며 “정 본부장을 사령탑으로 삼아 경선 승리를 넘어 본선 압승까지 질주하겠다”고 밝혔다. 김철민 동행캠프는 김철진 예비후보와의 정책연대를 기점으로, 시민들의 삶에 밀착한 안전·교육·복지 공약을 구체화하여 ‘준비된 시장’으로서의 면모를 시민들에게 적극 알려 나갈 계획이다. $(function() { const copyUrlOptions=document.querySelectorAll(".urlBtns, .sns_clipboard"); // 주소복사 이벤트 (v11-fl-v2 수정) copyUrlOptions.forEach(selector=>{ selector.addEventListener("click", (e)=>{ const target=e.target, targetBtn=target.closest("[data-clipboard-text]"); if (targetBtn===null) return; const url=targetBtn.getAttribute("data-clipboard-text")||""; Util.copyToClipboardToast(selector, '', url); }); }); // 사진 lightBox 이벤트 if (typeof ImageViewer != "undefined") { new ImageViewer(".photo-layout", 0); } }); 권영창 기자 p